import React, {useState} from 'react';
import {Alert, Platform, SafeAreaView, Text} from 'react-native';
import hotUpdate from 'react-native-ota-hot-update';

function App(): React.JSX.Element {
  const [progress, setProgress] = useState(0);
  const [loading, setLoading] = useState(false);

  const onCheckGitVersion = () => {
    hotUpdate.git.checkForGitUpdate({
      branch: Platform.OS === 'ios' ? 'iOS' : 'android',
      bundlePath:
        Platform.OS === 'ios'
          ? 'output/main.jsbundle'
          : 'output/index.android.bundle',
      url: 'https://github.com/HongQuang231/ota-host-app.git',
      onCloneFailed(msg: string) {
        Alert.alert('Clone project failed!', msg, [
          {
            text: 'Cancel',
            onPress: () => {},
            style: 'cancel',
          },
        ]);
      },
      onCloneSuccess() {
        Alert.alert('Clone project success!', 'Restart to apply the changes', [
          {
            text: 'OK',
            onPress: () => hotUpdate.resetApp(),
          },
          {
            text: 'Cancel',
            onPress: () => {},
            style: 'cancel',
          },
        ]);
      },
      onPullFailed(msg: string) {
        Alert.alert('Pull project failed!', msg, [
          {
            text: 'Cancel',
            onPress: () => {},
            style: 'cancel',
          },
        ]);
      },
      onPullSuccess() {
        Alert.alert('Pull project success!', 'Restart to apply the changes', [
          {
            text: 'OK',
            onPress: () => hotUpdate.resetApp(),
          },
          {
            text: 'Cancel',
            onPress: () => {},
            style: 'cancel',
          },
        ]);
      },
      onProgress(received: number, total: number) {
        const percent = (+received / +total) * 100;
        setProgress(percent);
      },
      onFinishProgress() {
        setLoading(false);
      },
    });
  };

  return (
    <SafeAreaView>
      <Text>2222</Text>
    </SafeAreaView>
  );
}

export default App;
